from revise import save,load
x=load('modern-da.json')['chapters'][0]['paragraphs']
save(1,16,{
6:x[5].replace('holdt hr. Ramsay med selskab','holdt hr. Ramsay selskab'),
9:x[8].replace('ringbesatte fingre og knipling','fingre med ringe og kniplinger').replace('så meget strengt','så strengt'),
10:'''»Vi kan ikke gå i land ved fyret i morgen,« sagde Charles Tansley og slog hænderne sammen, mens han stod ved vinduet sammen med hendes mand. Nu havde han vel sagt nok. Hun ønskede, at de begge ville lade hende og James være i fred og tale videre. Hun så på ham. Han var sådan et ynkeligt eksemplar, sagde børnene, lutter buler og fordybninger. Han kunne ikke spille cricket; han stak klodset til bolden; han slæbte på benene. Han var et sarkastisk bæst, sagde Andrew. De vidste, hvad han bedst kunne lide — bestandigt at gå op og ned, op og ned, sammen med hr. Ramsay og tale om, hvem der havde vundet det ene og det andet, hvem der var »førsteklasses« til latinske vers, hvem der var »strålende, men efter min mening grundlæggende usolid«, hvem der uden tvivl var »den dygtigste fyr på Balliol«, hvem der for en tid havde sat sit lys under en skæppe i Bristol eller Bedford, men nok skulle lade høre fra sig, når hans Prolegomena til en eller anden gren af matematikken eller filosofien så dagens lys — hr. Tansley havde de første sider i korrektur med sig, hvis hr. Ramsay ville se dem. Det var det, de talte om.''',
11:x[10].replace('Hun kunne ikke lade være med at le selv undertiden','Undertiden kunne hun heller ikke selv lade være med at le').replace('Jo, Charles Tansley var enig, det var lidt voldsomt','Ja, sagde Charles Tansley, der var lidt søgang'),
12:x[11].replace('aldrig kunne holde fred','ikke var tilfreds').replace('Gud ved, sagde Rose, at det kunne man ikke','Gud skulle vide, sagde Rose, at det kunne man ikke'),
13:'''Hr. og fru Ramsays otte sønner og døtre forsvandt lydløst som hjorte fra middagsbordet, så snart måltidet var slut, og søgte ind på deres værelser, deres fæstninger i et hus, hvor der ellers ikke var noget privatliv, for at diskutere hvad som helst, alt muligt: Tansleys slips; vedtagelsen af reformloven; havfugle og sommerfugle; mennesker. Imens strømmede solen ind i disse loftsværelser, som kun en bræddevæg skilte fra hinanden, så man tydeligt kunne høre hvert fodtrin og den schweiziske pige, der hulkede over sin far, som lå for døden af kræft i en dal i Graubünden. Solen lyste på cricketbat, flanelstøj, stråhatte, blækhuse, malerkrukker, biller og småfuglenes kranier og trak en lugt af salt og tang ud af de lange, krusede tangstrimler, der var fæstnet til væggen. Den samme lugt sad i håndklæderne, der var ru af sand fra badeturene.''',
14:x[13].replace('Det forekom hende så meget sludder','Det forekom hende at være sådan noget sludder').replace('velbårne','højadelige').replace('Al hendes vid','Alt hendes vid').replace('dybere grundede hun','mere indgående grublede hun').replace('ugentlig, daglig','hver uge, hver dag').replace('denne enke eller hin slidende hustru','en enke eller en kone, der kæmpede for at få det til at hænge sammen').replace('en privat kvinde','en kvinde, der handlede som privatperson').replace('en lise for hendes egen nysgerrighed','en tilfredsstillelse af hendes egen nysgerrighed'),
16:x[15].replace('et trist ærinde','et kedeligt ærinde').replace('hun ville være ti minutter måske','det ville måske tage ti minutter').replace('det mindste hint om','den mindste antydning af')
})
